section.sourcecode:
Envelope = #6.18([ protected: bstr .cbor ProtHdr, unprotected: {}, ; MUST be empty map; receivers ignore payload: bstr .cbor Body, signature: bstr .size 64 ; per negotiated suite (Ed25519 here) ])
ProtHdr = { 1 => -8, ; COSE alg: EdDSA 4 => AgentID, ; COSE kid: SENDER AgentID ? 33 => [+ bstr] ; x5chain-slot reused: delegation chain } ; (identity §6); order: leaf..root
Body = { 0 => Version, ; protocol-version (negotiated, §6) 1 => uint, ; msg-type (registry §11) 2 => MsgID, 3 => Timestamp, ? 4 => AgentID, ; recipient (REQUIRED in-session) ? 5 => uint, ; ttl-ms (store-and-forward objects) ? 6 => SessionID, ? 7 => uint, ; seq (REQUIRED in-session, §7.2) ? 8 => [* int], ; crit: ext keys receiver MUST grok ? 9 => ExtMap, ; extensions 10 => any ; content, per msg-type }

FlowCredit = {
  1 => TaskID / SessionID,   ; scope
  2 => uint,                 ; additional message credits
  3 => uint                  ; additional byte credits
}
